body .callout[data-callout*="svg-vortex"]  {
    --callout-icon: none;
	color: var(--lw);
	background-image: var(--gdj-vortex);
	background-size: 100% auto;
	background-position: 50% 0%;
	background-repeat: repeat;
}

.whim-border-vortex {
	border-style: solid;
	border-width: 10px;
	border-color: color-mix(in srgb, white, transparent 70%);
	border-image: var(--gdj-vortex) 20;
}

.whim-border-vortex-layer { 
	border-style: solid;
	border-width: 1px;
	border-color: color-mix(in srgb, white, transparent 70%);
	border-image: var(--gdj-vortex);
	border-image-width: auto;
	border-image-outset: 0 0 600 0;
	border-image-repeat: repeat;
}

.whim-hr-vortex {
	--hr-svg: var(--gdj-vortex);
}

.whim-bg-stamp-vortex {
	--stamp-svg: var(--gdj-vortex);
}

.whim-mask-vortex {
	-webkit-mask-image: var(--gdj-vortex), radial-gradient(black 50%, color-mix(in srgb, black, transparent 65%) 70%, color-mix(in srgb, black, transparent 100%) 90%);
}
.whim-mask-vortex-less {
	-webkit-mask-image: var(--gdj-vortex), radial-gradient(black 50%, color-mix(in srgb, black, transparent 50%) 70%);
}
.whim-mask-vortex-fade {
	-webkit-mask-image: var(--gdj-vortex), linear-gradient(black 65%, transparent 90%);
}
.whim-mask-vortex-fademore {
	-webkit-mask-image: var(--gdj-vortex), linear-gradient(black 35%, transparent 65%);
}
.whim-mask-vortex-simple {
	-webkit-mask-image: var(--gdj-vortex), linear-gradient(color-mix(in srgb, black, transparent 25%) 25%, color-mix(in srgb, black, transparent 50%) 75%);
}